  console.log('customer', customer.id);

  // attach payment method (sandbox succeed token)
  const pmRes = await fetch(`${BASE}/v1/customers/${customer.id}/payment-methods`, {
    method: 'POST', headers,
    body: JSON.stringify({ providerToken: 'tok_live_4242', type: 'card', brand: 'visa', last4: '4242', billingName: 'Pay Person', billingAddress: { line1: '1 Test Way' } }),
  });
  const pm = await pmRes.json();
  console.log('payment method', pmRes.status, pm);

  // create payment
  const paymentRes = await fetch(`${BASE}/v1/payments`, {
    method: 'POST', headers: { ...headers, 'idempotency-key': `pay-${Date.now()}` },
    body: JSON.stringify({ customerId: customer.id, amount: 5000, currency: 'usd', paymentMethodId: pm.id, description: 'Test payment' }),
  });
