  console.log('payment', paymentRes.status, payment);

  // wait for webhook processing (payment succeeded async)
  let paymentStatus = payment.status;
  let paymentId = payment.id;
  for (let i = 0; i < 20 && paymentStatus !== 'succeeded'; i++) {
    await new Promise((r) => setTimeout(r, 500));
    const res = await fetch(`${BASE}/v1/payments/${paymentId}`, { headers });
    const body = await res.json();
    paymentStatus = body.status;
  }
  console.log('final payment status', paymentStatus);

  // create invoice
  const invoiceRes = await fetch(`${BASE}/v1/invoices`, {
    method: 'POST', headers,
    body: JSON.stringify({ customerId: customer.id, currency: 'USD', lines: [{ description: 'Widget', quantity: 1, unitAmount: 5000 }] }),
  });
  const invoice = await invoiceRes.json();
  console.log('invoice', invoiceRes.status, invoice);

  // create refund
  const refundRes = await fetch(`${BASE}/v1/payments/${paymentId}/refunds`, {
    method: 'POST', headers,
    body: JSON.stringify({ amount: 1000, reason: 'customer request' }),
  });
  const refund = await refundRes.json();
  console.log('refund', refundRes.status, refund);
  await new Promise((r) => setTimeout(r, 1000));

  // now erase
  const erasureRes = await fetch(`${BASE}/v1/customers/${customer.id}/erasure-requests`, {
    method: 'POST', headers: { authorization: auth, 'idempotency-key': `erase-pay-${Date.now()}` },
  });
  const erasureBody = await erasureRes.json();
  console.log('erasure request', erasureRes.status, erasureBody);

  let status = erasureBody.status;
  for (let i = 0; i < 30 && status !== 'completed' && status !== 'failed'; i++) {
    await new Promise((r) => setTimeout(r, 500));
    const res = await fetch(`${BASE}/v1/erasure-requests/${erasureBody.id}`, { headers });
    const body = await res.json();
    status = body.status;
    console.log('poll', i, body.status, body.lastError);
  }

  // check payment record after erasure
  const paymentAfter = await fetch(`${BASE}/v1/payments/${paymentId}`, { headers });
  console.log('payment after erasure', paymentAfter.status, JSON.stringify(await paymentAfter.json(), null, 2));

  return { customerId: customer.id, paymentId, invoiceId: invoice.id, invoiceObjectKey: invoice.objectKey };
}

main().then((r) => console.log('RESULT', JSON.stringify(r))).catch((e) => { console.error(e); process.exit(1); });
